      \cvitem{Generated statutory reports (Form 16, Form 24Q) and conducted sessions on Statutory Policies, procedures, and compliance topics (e.g., Shops and Commercial Establishments Act (S\&E), The Payment of Gratuity Act 1972).}
      \cvitem{Handled full cycle Recruitment and Selection, from job posting on portals to coordination, manpower planning, budgeting, preliminary interviews, and orientation.}
      \cvitem{Managed employee joining formalities and salary account opening processes.}
      \cvitem{Facilitated end-to-end Performance Management System (PMS), including creating Job Descriptions, Appraisal Forms, KRA setting, Mid-year and Annual reviews, and 360-Degree appraisal activities.}
      \cvitem{Conducted Training Needs Analysis and arranged various training sessions.}
      \cvitem{Drove Employee Engagement and Welfare through creation and deployment of Sales Rewards and Recognition Schemes and periodic interactive sessions (e.g., Monthly Birthday Celebration, Annual Day, Diwali Dhamaka, Offsite).}
      \cvitem{Utilized Saral Payment Package payroll software and Excel for various HR operations.}
      \cvitem{Assisted MD in HR functions, offered suggestions, and resolved employee queries on payroll compliance, benefits (insurance, medical, reimbursement), and full \& final settlements.}
    \cvitemend
\cvheadingend

